head.script:
scwin.screenId = "jldbnf25000";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb1", fn: function () { return String(dma_result.get("isuAmt")) + " 원"; } },
        { childId: "__rb3", fn: function () { return String(dma_result.get("listAmt")) + " 원"; } },
        { childId: "__rb4", fn: function () { return String(dma_result.get("bfchgCoupnRt")) + " %"; } },
        { childId: "__rb10", fn: function () { return String(dma_result.get("spdSgn")) + " " + String(dma_result.get("spd")) + "%"; } },
        { childId: "ipt_intRtChgSeq", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("intRtChgSeq")))); } },
        { childId: "cal_intRtDecsnBasDd", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("intRtChgDd")))); } },
        { childId: "cal_intPayDd", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("intPayDd")))); } },
        { childId: "__rb11", fn: function () { return String(dma_result.get("bfchgCoupnRt")) + "% "; } },
        { childId: "__rb12", fn: function () { return String(dma_result.get("befBasInt")) + "% "; } },
        { childId: "__rb13", fn: function () { return String(dma_result.get("befSpdSgn")) + " " + String(dma_result.get("befSpd")) + "% "; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

