/**
 * @method
 * @name scwin.mpd_files_selectCallback
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

/**
 * @method
 * @name scwin.calcBasInt
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.calcBasInt = async function () {
    /* sdd-asis-lifecycle:begin fn_calc_bas_int — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.SendForm || { elements: [] });
    let sum = 0;
    if ($c.util.getComponent('slc_spdSgn').getValue()=== '+') {
        sum = parseFloat($c.util.getComponent('ipt_nxtpdBasInt').getValue()) + parseFloat($c.util.getComponent('ipt_spd').getValue());
    } else {
        if (parseFloat($c.util.getComponent('ipt_nxtpdBasInt').getValue()) < parseFloat($c.util.getComponent('ipt_spd').getValue())) {
            await $c.win.alert("가산금리부호가 '-'인 경우, 기준금리를 가산금리 보다 크게 입력하세요.");
            $c.util.getComponent("slc_spdSgn").setValue('+');
            return;
        }
        sum = parseFloat($c.util.getComponent('ipt_nxtpdBasInt').getValue()) - parseFloat($c.util.getComponent('ipt_spd').getValue());
    }
    if (sum >= 100) {
        await $c.win.alert("기준금리와 가산금리의 합은 '100 미만'으로 입력하세요.");
        $c.util.getComponent("ipt_nxtpdBasInt").setValue('');
        $c.util.getComponent("ipt_nxtpdBasInt").focus();
        return;
    }
    const fix_sum = sum.toFixed(5);
    $c.util.getComponent("ipt_basInt").setValue(fix_sum.replace(/0+$/, ""));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setTelNo
 * @author Inswave
 * @date 2026. 09. 29
 * @param pTelNo
 * @returns
 * @hidden N
*/
scwin.setTelNo = function (pTelNo) {
    /* sdd-asis-lifecycle:begin setTelNo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (pTelNo != null && pTelNo !== '') {
