/**
 * @method
 * @name scwin.rtNoChange
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.rtNoChange = async function () {
    /* sdd-asis-lifecycle:begin fn_RtNoChange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const bfchg_coupn_rt = $c.util.getComponent('ipt_bfchgCoupnRt').getValue();
    const bef_bas_int = $c.util.getComponent('ipt_befBasInt').getValue(); if (bef_bas_int == null) { bef_bas_int = ''; }
    const bef_spd_sgn = $c.util.getComponent('ipt_befSpdSgn').getValue(); if (bef_spd_sgn == null) { bef_spd_sgn = ''; }
    const bef_spd = $c.util.getComponent('ipt_befSpd').getValue(); if (bef_spd == null) { bef_spd = ''; }
    if (bef_bas_int === "" || bef_spd_sgn === "" || bef_spd === "") {
        await $c.win.alert("변경전 기준금리 또는 가산금리 값이 존재하지 않습니다.\n직접 입력하시기 바랍니다.");
    }
    $c.util.getComponent('ipt_basInt').setValue(bfchg_coupn_rt);
    $c.util.getComponent('ipt_nxtpdBasInt').setValue(bef_bas_int);
    $c.util.getComponent('slc_spdSgn').setValue(bef_spd_sgn);
    $c.util.getComponent('ipt_spd').setValue(bef_spd);
    /* sdd-asis-lifecycle:end */
};


// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
/**
 * @method
 * @name scwin.getBdchrgInfoDone
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.getBdchrgInfoDone = function (data) {
    /* sdd-asis-lifecycle:begin fn_GetBdchrgInfo_done — as-is 원문 본문(전환 이관 · 포팅 적용됨) */const result = (typeof data === "string" ? JSON.parse(data) : data);
    $c.util.getComponent('ipt_chrgId').setValue(result.chrg_id);
    $c.util.getComponent('ipt_apctNm').setValue(result.chrg_nm);
    $c.util.getComponent('ipt_jobposNm').setValue(result.jobpos_nm);
    $c.util.getComponent('ipt_belngInstNm').setValue(result.belng_inst_nm);
    $c.util.getComponent('ipt_belngDepNm').setValue(result.belng_dep_nm);
    scwin.setTelNo(result.tel_no);
    scwin.setCellphoneNo(result.cellphone_no);
    scwin.setEmail(result.email);
    scwin.setFaxNo(result.fax_no);
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.getBdchrgInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.getBdchrgInfo = async function () {
    const r = await scwin.tx_fn_GetBdchrgInfo();
    try {
        scwin.getBdchrgInfoDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldbnf25000.fn_GetBdchrgInfo' });
    }
    return r;
};
